{
  "ok": true,
  "tool": "list_operations",
  "operations": [
    {
      "op": "array_polar",
      "category": "edit",
      "description": "Polar array about a center: 'count' items (including the original) over 'total_angle'.",
      "params": {
        "type": "object",
        "properties": {
          "target": {
            "description": "Entities to operate on — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "center": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Array center [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "count": {
            "type": "integer",
            "description": "Total number of items including the original",
            "minimum": 2,
            "maximum": 10000
          },
          "total_angle": {
            "type": "number",
            "description": "Angle to fill (degrees, counter-clockwise)",
            "default": 360.0
          },
          "rotate_items": {
            "type": "boolean",
            "description": "Rotate the copies (else only translate)",
            "default": true
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "target",
          "center",
          "count"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "array_rect",
      "category": "edit",
      "description": "Rectangular array: copies arranged in rows and columns (the original is cell [0,0]).",
      "params": {
        "type": "object",
        "properties": {
          "target": {
            "description": "Entities to operate on — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "rows": {
            "type": "integer",
            "description": "Number of rows",
            "minimum": 1,
            "maximum": 1000
          },
          "cols": {
            "type": "integer",
            "description": "Number of columns",
            "minimum": 1,
            "maximum": 1000
          },
          "row_spacing": {
            "type": [
              "number",
              "string"
            ],
            "description": "Distance between rows (Y) (drawing units, or string with unit e.g. '8mm')",
            "default": 0.0
          },
          "col_spacing": {
            "type": [
              "number",
              "string"
            ],
            "description": "Distance between columns (X) (drawing units, or string with unit e.g. '8mm')",
            "default": 0.0
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "target",
          "rows",
          "cols"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "chamfer",
      "category": "edit",
      "description": "AutoCAD CHAMFER of two LINEs with distances d1 (on line1) and d2 (on line2).",
      "params": {
        "type": "object",
        "properties": {
          "line1": {
            "description": " — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "line2": {
            "description": " — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "d1": {
            "type": [
              "number",
              "string"
            ],
            "description": " (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0
          },
          "d2": {
            "type": [
              "number",
              "string"
            ],
            "description": "Defaults to d1 (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0
          },
          "layer": {
            "type": "string",
            "description": "Layer name (created on the fly if missing)"
          },
          "color": {
            "type": "integer",
            "description": "ACI color (256 = BYLAYER)",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
            "type": "string",
            "description": "Linetype name, e.g. CONTINUOUS, CENTER, DASHED"
          },
          "lineweight": {
            "type": "integer",
            "description": "Lineweight in 1/100 mm (e.g. 50 = 0.50 mm), -1 = BYLAYER"
          },
          "tag": {
            "type": "string",
            "description": "Semantic tag for later reference as 'tag:<name>'"
          },
          "if_tag_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip",
              "replace"
            ],
            "description": "Behaviour when an entity with this tag already exists (use 'skip' for idempotent replays)",
            "default": "error"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "line1",
          "line2",
          "d1"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "copy",
      "category": "edit",
      "description": "Copy entities by a displacement; 'count' > 1 repeats the displacement cumulatively.",
      "params": {
        "type": "object",
        "properties": {
          "target": {
            "description": "Entities to operate on — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "delta": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Displacement [dx, dy] [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "base": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Base point [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "to": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Destination of the base point [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "count": {
            "type": "integer",
            "description": "Number of copies",
            "minimum": 1,
            "maximum": 10000,
            "default": 1
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "target"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "delete",
      "category": "edit",
      "description": "Erase entities. Deleting more than the policy threshold needs confirm_large=true.",
      "params": {
        "type": "object",
        "properties": {
          "target": {
            "description": "Entities to operate on — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "confirm_large": {
            "type": "boolean",
            "description": "Confirm a large deletion",
            "default": false
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "target"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "explode",
      "category": "edit",
      "description": "Explode block references (INSERT) or polylines into their component entities.",
      "params": {
        "type": "object",
        "properties": {
          "target": {
            "description": "Entities to operate on — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "target"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "extend",
      "category": "edit",
      "description": "AutoCAD EXTEND: lengthen a LINE end until it meets the nearest boundary edge.",
      "params": {
        "type": "object",
        "properties": {
          "target": {
            "description": "Single LINE — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "edges": {
            "description": "Boundary edges — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "end": {
            "type": "string",
            "enum": [
              "start",
              "end",
              "auto"
            ],
            "description": "Which end to extend ('auto' = the end nearer to an intersection)",
            "default": "auto"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "target",
          "edges"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "fillet",
      "category": "edit",
      "description": "AutoCAD FILLET of two LINEs: trims/extends both to tangency and adds a tangent ARC (radius 0 = sharp corner).",
      "params": {
        "type": "object",
        "properties": {
          "line1": {
            "description": " — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "line2": {
            "description": " — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "radius": {
            "type": [
              "number",
              "string"
            ],
            "description": " (drawing units, or string with unit e.g. '8mm')",
            "minimum": 0
          },
          "layer": {
            "type": "string",
            "description": "Layer name (created on the fly if missing)"
          },
          "color": {
            "type": "integer",
            "description": "ACI color (256 = BYLAYER)",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
            "type": "string",
            "description": "Linetype name, e.g. CONTINUOUS, CENTER, DASHED"
          },
          "lineweight": {
            "type": "integer",
            "description": "Lineweight in 1/100 mm (e.g. 50 = 0.50 mm), -1 = BYLAYER"
          },
          "tag": {
            "type": "string",
            "description": "Semantic tag for later reference as 'tag:<name>'"
          },
          "if_tag_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip",
              "replace"
            ],
            "description": "Behaviour when an entity with this tag already exists (use 'skip' for idempotent replays)",
            "default": "error"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "line1",
          "line2",
          "radius"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "mirror",
      "category": "edit",
      "description": "Mirror entities about the line p1-p2. Text stays readable (MIRRTEXT=0).",
      "params": {
        "type": "object",
        "properties": {
          "target": {
            "description": "Entities to operate on — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "p1": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "First point of mirror line [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "p2": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Second point of mirror line [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "keep_original": {
            "type": "boolean",
            "description": "Keep the source entities (mirror a copy)",
            "default": true
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "target",
          "p1",
          "p2"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "modify",
      "category": "edit",
      "description": "Set fields of ONE entity, e.g. {target, set: {radius: 5}} for a circle, {set: {start: [0,0], end: [10,0]}} for a line, {set: {points: [...], closed: true}} for a polyline, {set: {text: 'A'}} for text, {set: {text: '4X <>', text_height: 3.5, length_factor: 2}} for a dimension.",
      "params": {
        "type": "object",
        "properties": {
          "target": {
            "description": "Entities to operate on — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "set": {
            "type": "object",
            "description": "Field -> new value"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "target",
          "set"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "move",
      "category": "edit",
      "description": "Translate entities by a displacement (or from 'base' to 'to').",
      "params": {
        "type": "object",
        "properties": {
          "target": {
            "description": "Entities to operate on — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "delta": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Displacement [dx, dy] [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "base": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Base point [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "to": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Destination of the base point [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "target"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "offset",
      "category": "edit",
      "description": "Create an offset copy of a LINE, CIRCLE, ARC or straight-segment LWPOLYLINE. The side is given by 'side_point' (preferred) or by the sign of 'distance' (positive = left of line direction / outside of circles and closed polylines).",
      "params": {
        "type": "object",
        "properties": {
          "target": {
            "description": "Entities to operate on — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "distance": {
            "type": [
              "number",
              "string"
            ],
            "description": "Offset distance (drawing units, or string with unit e.g. '8mm')"
          },
          "side_point": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "A point on the side to offset towards [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "layer": {
            "type": "string",
            "description": "Layer name (created on the fly if missing)"
          },
          "color": {
            "type": "integer",
            "description": "ACI color (256 = BYLAYER)",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
            "type": "string",
            "description": "Linetype name, e.g. CONTINUOUS, CENTER, DASHED"
          },
          "lineweight": {
            "type": "integer",
            "description": "Lineweight in 1/100 mm (e.g. 50 = 0.50 mm), -1 = BYLAYER"
          },
          "tag": {
            "type": "string",
            "description": "Semantic tag for later reference as 'tag:<name>'"
          },
          "if_tag_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip",
              "replace"
            ],
            "description": "Behaviour when an entity with this tag already exists (use 'skip' for idempotent replays)",
            "default": "error"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "target",
          "distance"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "rotate",
      "category": "edit",
      "description": "Rotate entities about a center point (degrees, CCW).",
      "params": {
        "type": "object",
        "properties": {
          "target": {
            "description": "Entities to operate on — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "angle": {
            "type": "number",
            "description": "Rotation angle (degrees, counter-clockwise)"
          },
          "center": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Rotation center [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "target",
          "angle",
          "center"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "scale",
      "category": "edit",
      "description": "Uniformly scale entities about a base point.",
      "params": {
        "type": "object",
        "properties": {
          "target": {
            "description": "Entities to operate on — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "factor": {
            "type": "number",
            "description": "Scale factor",
            "exclusiveMinimum": 0
          },
          "center": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Base point [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "target",
          "factor",
          "center"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "set_properties",
      "category": "edit",
      "description": "Change layer / color / linetype / lineweight / tag of entities.",
      "params": {
        "type": "object",
        "properties": {
          "target": {
            "description": "Entities to operate on — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "layer": {
            "type": "string",
            "description": ""
          },
          "color": {
            "type": "integer",
            "description": "",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
            "type": "string",
            "description": ""
          },
          "lineweight": {
            "type": "integer",
            "description": ""
          },
          "tag": {
            "type": "string",
            "description": "New tag (only valid for a single entity)"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "target"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "stretch",
      "category": "edit",
      "description": "AutoCAD STRETCH with a crossing window: entities entirely inside move; LINE end points, polyline vertices and dimension definition points inside the window move; circles/arcs/text/blocks move if their center/insert point is inside. Dimensions are re-measured.",
      "params": {
        "type": "object",
        "properties": {
          "window": {
            "type": "array",
            "items": {
              "type": "array"
            },
            "description": "Two opposite corners of the crossing window list of [x, y] (or [x, y, bulge]) (drawing units, or string with unit e.g. '8mm')"
          },
          "delta": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Displacement [dx, dy] [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "window",
